(function () {
  var display = document.querySelector('[data-testid="calc-display"]');
  var opButtons = document.querySelectorAll('[data-op]');
  var tape = document.querySelector('[data-testid="calc-tape"]');
  var OP_SYMBOLS = { '+': '+', '-': '−', '*': '×', '/': '÷' };

  // entry: string being typed, or null when showing a stored value.
  // value: number currently shown when entry is null.
  // operand: true when value came from ± or ) and is the next operand, like
  // a typed entry, but further digits start a new entry instead of appending.
  // groups: one saved { stored, op, tok } per open parenthesis, innermost last.
  // tokens: the expression so far, for the tape. groupTok: index of the "("
  // token when the operand is a just-closed group, whose tokens are already
  // in the expression; otherwise null.
  var state;

  function reset() {
    state = { entry: null, value: 0, stored: null, op: null, operand: false, error: false, groups: [],
              tokens: [], groupTok: null };
  }

  // Add the operand being consumed to the expression, unless it is a closed
  // group already written there.
  function pushOperand(n) {
    if (state.groupTok === null) state.tokens.push(formatValue(n));
    state.groupTok = null;
  }

  function isOpToken(t) {
    return t === '+' || t === '−' || t === '×' || t === '÷';
  }

  function joinTokens(tokens) {
    var out = '';
    for (var i = 0; i < tokens.length; i++) {
      var t = tokens[i];
      var prev = tokens[i - 1];
      var tight = i === 0 || t === ')' || prev === '(' || prev === '-(';
      out += (tight ? '' : ' ') + t;
    }
    return out;
  }

  function addTapeRow(expr, value) {
    var row = document.createElement('div');
    row.className = 'tape-row';
    row.setAttribute('data-testid', 'tape-row');
    var exprEl = document.createElement('div');
    exprEl.className = 'tape-expr';
    exprEl.setAttribute('data-testid', 'tape-expr');
    exprEl.textContent = expr;
    var resultEl = document.createElement('div');
    resultEl.className = 'tape-result';
    resultEl.setAttribute('data-testid', 'tape-result');
    resultEl.setAttribute('data-value', String(value));
    resultEl.textContent = formatValue(value);
    row.appendChild(exprEl);
    row.appendChild(resultEl);
    tape.insertBefore(row, tape.firstChild);
  }

  function compute(a, op, b) {
    switch (op) {
      case '+': return a + b;
      case '-': return a - b;
      case '*': return a * b;
      case '/': return a / b;
    }
    return b;
  }

  function currentNumber() {
    return state.entry !== null ? parseFloat(state.entry) : state.value;
  }

  // Presentation only: round to at most 10 significant digits for the visible
  // text. The stored value is never rounded, so chains stay exact.
  // Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
  function formatValue(n) {
    if (n === 0) return '0';
    var parts = Math.abs(n).toExponential(9).split('e');
    var digits = parts[0].replace('.', '');
    var exp = parseInt(parts[1], 10);
    var sign = n < 0 ? '-' : '';
    if (exp >= 10 || exp < -9) {
      var mantissa = trimFraction(digits.charAt(0), digits.slice(1));
      return sign + mantissa + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
    }
    if (exp >= 0) {
      return sign + trimFraction(digits.slice(0, exp + 1), digits.slice(exp + 1));
    }
    return sign + trimFraction('0', new Array(-exp).join('0') + digits);
  }

  function trimFraction(intPart, frac) {
    frac = frac.replace(/0+$/, '');
    return frac ? intPart + '.' + frac : intPart;
  }

  function render() {
    var text;
    if (state.error) {
      text = 'Error';
    } else if (state.entry !== null) {
      text = state.entry;
    } else {
      text = formatValue(state.value);
    }
    display.textContent = text;
    display.setAttribute('data-value', state.error ? 'NaN' : String(currentNumber()));
    display.setAttribute('data-error', state.error ? 'true' : 'false');

    var len = text.length;
    display.style.fontSize = len > 16 ? '20px' : len > 12 ? '28px' : len > 9 ? '36px' : '48px';

    for (var i = 0; i < opButtons.length; i++) {
      var b = opButtons[i];
      b.classList.toggle('active', state.entry === null && !state.operand && state.op === b.getAttribute('data-op'));
    }
  }

  // A new entry right after ) replaces the group's result, so the group
  // leaves the expression too.
  function dropGroupOperand() {
    if (state.groupTok === null) return;
    state.tokens.length = state.groupTok;
    state.groupTok = null;
  }

  // In the error state every key except clear is ignored.
  function inputDigit(d) {
    if (state.error) return;
    dropGroupOperand();
    state.operand = false;
    if (state.entry === null || state.entry === '0') {
      state.entry = d;
    } else if (state.entry === '-0') {
      state.entry = '-' + d;
    } else {
      state.entry += d;
    }
  }

  function inputDot() {
    if (state.error) return;
    dropGroupOperand();
    state.operand = false;
    if (state.entry === null) {
      state.entry = '0.';
    } else if (state.entry.indexOf('.') === -1) {
      state.entry += '.';
    }
  }

  // ± acts on the shown number at once. A typed entry keeps its text,
  // so 0 ± 5 gives -5.
  function inputSign() {
    if (state.error) return;
    if (state.entry !== null) {
      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
    } else {
      state.value = -state.value;
      state.operand = true;
      if (state.groupTok !== null) {
        state.tokens[state.groupTok] = state.tokens[state.groupTok] === '(' ? '-(' : '(';
      }
    }
  }

  function setResult(n) {
    if (!isFinite(n)) {
      reset();
      state.error = true;
      return;
    }
    state.value = n;
  }

  // Immediate execution, strictly left to right, no operator precedence:
  // an operator key first applies the operation already waiting, so the
  // display always shows a real running result. 2 + 3 × 4 = is 20, not 14.
  function inputOp(op) {
    if (state.error) return;
    if (state.entry !== null || state.operand) {
      var n = currentNumber();
      state.entry = null;
      state.operand = false;
      pushOperand(n);
      if (state.op !== null && state.stored !== null) {
        setResult(compute(state.stored, state.op, n));
        if (state.error) return;
      } else {
        state.value = n;
      }
    } else if (isOpToken(state.tokens[state.tokens.length - 1])) {
      // A second operator in a row replaces the first.
      state.tokens.pop();
    } else {
      state.tokens.push(formatValue(state.value));
    }
    state.stored = state.value;
    state.op = op;
    state.tokens.push(OP_SYMBOLS[op]);
  }

  // Finish the operation waiting at the current level, as = does.
  function finishLevel() {
    state.operand = false;
    if (state.op === null) {
      if (state.entry !== null) {
        state.value = parseFloat(state.entry);
        state.entry = null;
      }
      pushOperand(state.value);
      return;
    }
    var b = currentNumber();
    state.entry = null;
    pushOperand(b);
    var op = state.op;
    state.op = null;
    var a = state.stored;
    state.stored = null;
    setResult(compute(a, op, b));
  }

  // ( saves the waiting operation and starts a fresh one inside the group.
  // Right after a number, ( multiplies it by the group: 2 ( 3 ) is 6.
  function openGroup() {
    if (state.error) return;
    if (state.entry !== null || state.operand) {
      inputOp('*');
      if (state.error) return;
    }
    state.groups.push({ stored: state.stored, op: state.op, tok: state.tokens.length });
    state.tokens.push('(');
    state.entry = null;
    state.value = 0;
    state.stored = null;
    state.op = null;
    state.operand = false;
  }

  // ) finishes the group and hands its result back as the next operand.
  function closeGroup() {
    if (state.error || state.groups.length === 0) return;
    finishLevel();
    if (state.error) return;
    var outer = state.groups.pop();
    state.stored = outer.stored;
    state.op = outer.op;
    state.operand = true;
    state.tokens.push(')');
    state.groupTok = outer.tok;
  }

  // = closes any groups still open, then finishes the calculation.
  // A calculation with at least one operator goes on the tape; the result
  // then starts a fresh expression.
  function equals() {
    if (state.error) return;
    while (state.groups.length > 0) {
      closeGroup();
      if (state.error) return;
    }
    finishLevel();
    if (state.error) return;
    if (state.tokens.some(isOpToken)) addTapeRow(joinTokens(state.tokens), state.value);
    state.tokens = [];
    state.groupTok = null;
  }

  document.querySelector('.keys').addEventListener('click', function (e) {
    var btn = e.target.closest('button');
    if (!btn) return;
    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
    else {
      var action = btn.getAttribute('data-action');
      if (action === 'dot') inputDot();
      else if (action === 'sign') inputSign();
      else if (action === 'lparen') openGroup();
      else if (action === 'rparen') closeGroup();
      else if (action === 'equals') equals();
      else if (action === 'clear') reset();
    }
    render();
  });

  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
    tape.textContent = '';
  });

  document.addEventListener('keydown', function (e) {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    var k = e.key;
    if (/^[0-9]$/.test(k)) inputDigit(k);
    else if (k === '.' || k === ',') inputDot();
    else if (k === '+' || k === '-' || k === '*' || k === '/') inputOp(k);
    else if (k === '(') openGroup();
    else if (k === ')') closeGroup();
    else if (k === 'Enter' || k === '=') equals();
    else if (k === 'Escape' || k === 'c' || k === 'C') reset();
    else return;
    e.preventDefault();
    render();
  });

  reset();
  render();
})();
</script>
</body>
</html>

